SELECT COUNT(*) FROM "DataFlow" WHERE flow_overview->'performance'->>'data_size_mb' IS NOT NULL 
AND CAST(flow_overview->'performance'->>'data_size_mb' AS numeric) * 
        CASE WHEN flow_overview->'classification'->>'sensitivity_level' = 'High' THEN 3 ELSE 1 END > 100;

SELECT COUNT(DISTINCT df.flow_overview->'routing'->>'destination_country') as total,
       COUNT(DISTINCT CASE WHEN df.flow_overview->'routing'->>'destination_country' IS NOT NULL AND df.flow_overview->'routing'->>'destination_country' != 'None' THEN df.flow_overview->'routing'->>'destination_country' END) as filtered
FROM "DataFlow" df;

SELECT COUNT(*) FROM (
    SELECT df.flow_overview->'routing'->>'destination_country' AS destination_country
    FROM "DataFlow" df
    WHERE df.flow_overview->'routing'->>'destination_country' IS NOT NULL AND df.flow_overview->'routing'->>'destination_country' != 'None'
    GROUP BY df.flow_overview->'routing'->>'destination_country'
) t;
